import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0047: Native graph controls and session charts","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0047-native-graph-controls-and-session-charts.md","filePath":"adrs/0047-native-graph-controls-and-session-charts.md","lastUpdated":1789092097000}`),u={name:`adrs/0047-native-graph-controls-and-session-charts.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[12]||=a(`<h1 id="adr-0047-native-graph-controls-and-session-charts" tabindex="-1">ADR-0047: Native graph controls and session charts <a class="header-anchor" href="#adr-0047-native-graph-controls-and-session-charts" aria-label="Permalink to “ADR-0047: Native graph controls and session charts”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-06 · Refines <a href="/adrs/0031-provider-aware-llm-wiki-map">ADR-0031</a> and <a href="/adrs/0046-scoped-recent-memory-and-hindsight-map">ADR-0046</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`Dense memory maps need a stable focus, readable labels, and direct camera controls. The previous hover-only interaction and app-wide event monitors made exploration difficult. The chat inspector also exposed only a few generation numbers, despite the application already maintaining `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[0]||=[i(`context`,-1)]]),_:1}),l[2]||=i(` budgets, engine statistics, and coalesced live token estimates.`,-1)]),l[13]||=c(`h2`,{id:`decision`,tabindex:`-1`},[i(`Decision `),c(`a`,{class:`header-anchor`,href:`#decision`,"aria-label":`Permalink to “Decision”`},`​`)],-1),c(`p`,null,[l[4]||=i(`Keep two native rendering `,-1),r(m,{term:`tool`},{default:n(()=>[...l[3]||=[i(`tools`,-1)]]),_:1}),l[5]||=i(` with distinct purposes: SwiftUI Canvas renders graph topology; Apple Swift Charts renders quantitative context, throughput, and response comparisons. No new package, web renderer, network request, or persisted analytics is introduced.`,-1)]),c(`p`,null,[l[7]||=i(`The graph retains the existing provider validation, node/edge caps, and detached deterministic layout. Its view adds collision-avoiding labels, curved links, pinned focus, bounded search, a neighborhood filter, and an expanded sheet. Clicking pins a node; the focus panel's Open button opens the existing record preview. Wiki link direction uses arrowheads around the focused node; `,-1),r(m,{term:`hindsight`},{default:n(()=>[...l[6]||=[i(`Hindsight`,-1)]]),_:1}),l[8]||=i(` relationships do not imply curated wiki direction. Fixed vector emphasis replaces the continuous particle animation, including when Reduce Motion is enabled.`,-1)]),l[14]||=c(`p`,null,`Camera math lives in a finite, bounded value type. The viewport requires a click to activate and releases input when the pointer leaves, keyboard focus moves, or the scene becomes inactive. A visible badge names its state, and an inactive map passes page scrolling through unchanged. Drag pans, scroll/pinch zoom, right-drag rotates, and the toolbar provides zoom, fit, and rotation actions. Keyboard +, -, and 0 operate the focused viewport. Native event monitors belong to the exact visible viewport and key window, use weak ownership, and are removed when the view disappears. Expanded-map record selection is handed off after dismissal so it cannot compete with the record preview sheet.`,-1),l[15]||=c(`p`,null,`The inspector's Nerd stats card uses the existing ContextStatus for a context-pressure ring, including its input reserve and unknown/estimated states. Context additions saturate on overflow; nonpositive capacities never become a plausible percentage. The live throughput area/line chart samples existing byte-based text-plus-reasoning estimates once per second while the inspector is visible and its scene is active. A bounded 60-sample series records interval rates, including zero for stalls. Pause/resume establishes a new baseline, and a new generation resets the series. Closing the inspector cancels sampling; no background sampler or telemetry file exists.`,-1),c(`p`,null,[l[10]||=i(`Up to 12 recent completed response statistics produce comparison bars. Engine-reported decode rates and duration-derived rates have distinct colors and labels. Invalid rates are omitted, unknown context is not drawn as zero, and estimates retain the ~ qualifier. Comparisons may span `,-1),r(m,{term:`model`},{default:n(()=>[...l[9]||=[i(`models`,-1)]]),_:1}),l[11]||=i(` and settings and are explicitly not a benchmark. Existing persistence is unchanged; live traces are session UI state and disappear on reload.`,-1)]),l[16]||=a(`<h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Both graph surfaces share bounded rendering, camera behavior, and accessible native controls.</li><li>The inspector becomes useful during inference without adding endpoint probes or transcript scans for live measurement. Timing and token estimation remain distinct from authoritative server data.</li><li>The graph remains a bounded preview, not the full Hindsight explorer. Search covers loaded nodes.</li><li>The graph has no permanent animation loop. Sampling is 1 Hz only during a visible active response.</li><li>Tests cover camera anchors/limits/invalid input, rate capacity/pause/stalls, exact-versus-derived metrics, and context overflow. Existing graph validation and routing tests remain applicable.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>A third-party general-purpose graph package or embedded web dashboard would add dependencies and lifetime complexity. A pie of token categories would suggest a breakdown the engine does not reliably report. An unbounded, persisted high-frequency performance trace would add storage and rendering cost without improving the compact inspector.</p>`,4)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};